(7479567, 1189508, 182284, '<td valign="top">I''ve been there. Such amazing creatures. Loved the photo.10</td>', 'I''ve been there. Such amazing creatures. Loved the photo.10', '2016-10-26 01:36:52.000000', NULL, 1),
(7479574, 1189611, 67688, '<td valign="top">Great capture ..I used to work round the corner so I know this site really well. Great to see this with hardly any folk in the normally crowded site.. Be really interested to know what time of the morning this was taken. Should be on the front page.</td>', 'Great capture ..I used to work round the corner so I know this site really well. Great to see this with hardly any folk in the normally crowded site.. Be really interested to know what time of the morning this was taken. Should be on the front page.', '2016-10-26 03:45:36.000000', NULL, 1),
