(7479580, 1189677, 67688, '<td valign="top">Wow.. what a great capture... this both looks and feels old and majestic and gives a famous landmark that been shot umpteen times a new look and feel. Love the lighting and details..be interested to know the shooting details. Top three fro sure if not the winner... excellent..</td>', 'Wow.. what a great capture... this both looks and feels old and majestic and gives a famous landmark that been shot umpteen times a new look and feel. Love the lighting and details..be interested to know the shooting details. Top three fro sure if not the winner... excellent..', '2016-10-26 04:07:31.000000', NULL, 1),
(7479588, 1189652, 114285, '<td valign="top">Sharp and edited well. I really love this perspective, not sure I''ve seen it before like this, so kudos to you! Front page for you!</td>', 'Sharp and edited well. I really love this perspective, not sure I''ve seen it before like this, so kudos to you! Front page for you!', '2016-10-26 07:31:12.000000', NULL, 1),
