(7480169, 1189664, 135744, '<td valign="top">New York! New York! This surely must be the work of the very talented Niall. Love the duplicate capture in the cell phone. The photo really captures the atmosphere and the processing works well. Apologies if this was not by Niall - my comments still hold strong either way.</td>', 'New York! New York! This surely must be the work of the very talented Niall. Love the duplicate capture in the cell phone. The photo really captures the atmosphere and the processing works well. Apologies if this was not by Niall - my comments still hold strong either way.', '2016-11-01 07:03:12.000000', NULL, 1),
(7480328, 1189674, 16148, '<td valign="top">Amazing timing!  A few minutes later, after the roof fell in, wouldn''t be as strong an image.  Nicely done.</td>', 'Amazing timing!  A few minutes later, after the roof fell in, wouldn''t be as strong an image.  Nicely done.', '2016-11-01 14:35:00.000000', NULL, 1),
(7480329, 1189561, 16148, '<td valign="top">Such a simple image that usually wouldn''t hold my attention.  Your presentation, lead on rag paper, works for me.</td>', 'Such a simple image that usually wouldn''t hold my attention.  Your presentation, lead on rag paper, works for me.', '2016-11-01 14:37:30.000000', NULL, 1),
