(7480341, 1189664, 70270, '<td valign="top">a different landmark, but a landmark nonetheless. lots of energy. like the processing too.</td>', 'a different landmark, but a landmark nonetheless. lots of energy. like the processing too.', '2016-11-01 19:24:03.000000', NULL, 1),
(7480343, 1189638, 70270, '<td valign="top">nice shot but more about the sky then the mark, and not striking enough as a silhouette.  Would like more detail in the building, perhaps an HDR.  YMMV, but to me it misses the mark.</td>', 'nice shot but more about the sky then the mark, and not striking enough as a silhouette.  Would like more detail in the building, perhaps an HDR.  YMMV, but to me it misses the mark.', '2016-11-01 19:25:17.000000', NULL, 1),
