(7480362, 1189568, 138630, '<td valign="top">Excellent textures and tones.  Is that a smokestack?  Tough to include in the composition, but you did a nice job of it.</td>', 'Excellent textures and tones.  Is that a smokestack?  Tough to include in the composition, but you did a nice job of it.', '2016-11-01 21:18:06.000000', NULL, 1),
(7480363, 1189677, 138630, '<td valign="top">Excellent detail and rich tones.  The night shot and close-up both work for me.</td>', 'Excellent detail and rich tones.  The night shot and close-up both work for me.', '2016-11-01 21:18:53.000000', NULL, 1),
(7480364, 1189653, 138630, '<td valign="top">I like the processing a lot - the tilt, too, though I kind if wish it went the other way as I feel like it''s falling on me.</td>', 'I like the processing a lot - the tilt, too, though I kind if wish it went the other way as I feel like it''s falling on me.', '2016-11-01 21:19:42.000000', NULL, 1),
(7480365, 1189627, 138630, '<td valign="top">I like the tonal range and the shutter speed on the water but the focus otherwise is a little too soft for me for the scene.</td>', 'I like the tonal range and the shutter speed on the water but the focus otherwise is a little too soft for me for the scene.', '2016-11-01 21:22:05.000000', NULL, 1),
(7480366, 1189534, 138630, '<td valign="top">Who (or where) is Karl?  I love the top half - not so much the land mass on the right though it does anchor the scene.</td>', 'Who (or where) is Karl?  I love the top half - not so much the land mass on the right though it does anchor the scene.', '2016-11-01 21:23:50.000000', NULL, 1),
(7480367, 1189469, 138630, '<td valign="top">Love the silhouette.  I''m not crazy about the tones or the composition - half black is too much for me.</td>', 'Love the silhouette.  I''m not crazy about the tones or the composition - half black is too much for me.', '2016-11-01 21:24:43.000000', NULL, 1),
(7480368, 1189652, 138630, '<td valign="top">Nice perspective and tones - I like the processing here.  It rains a lot in Paris - good to see you making the most of it.</td>', 'Nice perspective and tones - I like the processing here.  It rains a lot in Paris - good to see you making the most of it.', '2016-11-01 21:26:32.000000', NULL, 1),
(7480369, 1189638, 138630, '<td valign="top">I wish there was a way to get a little more definition in the trees and dome - more windows and spaced branches or something.  The silhouette is nice but a little heavy feeling.</td>', 'I wish there was a way to get a little more definition in the trees and dome - more windows and spaced branches or something.  The silhouette is nice but a little heavy feeling.', '2016-11-01 21:28:02.000000', NULL, 1),
(7480387, 1189633, 97225, '<td valign="top">Fabulous colours!</td>', 'Fabulous colours!', '2016-11-01 22:25:13.000000', NULL, 1),
(7480388, 1189607, 97225, '<td valign="top">Great shot of a great landmark. My choice for the blue. 10</td>', 'Great shot of a great landmark. My choice for the blue. 10', '2016-11-01 22:26:09.000000', NULL, 1),
(7480390, 1189276, 97225, '<td valign="top">What a great landmark! I still remember seeing this for the first time when I was about 12 (over half a century ago). It was like a physical blow - literally took my breath away.</td>', 'What a great landmark! I still remember seeing this for the first time when I was about 12 (over half a century ago). It was like a physical blow - literally took my breath away.', '2016-11-01 22:29:15.000000', NULL, 1),
