(7480407, 1189627, 114285, '<td valign="top">Well Margaret, so you made it to Iceland,  how fantastic is that!!<br/>Congrats <br/></td>', 'Well Margaret, so you made it to Iceland,  how fantastic is that!!Congrats ', '2016-11-02 00:17:13.000000', NULL, 0),
